def predict_both(grid):
    """Fill uniform columns AND uniform rows with 2s"""
    result = [row[:] for row in grid]
    n_rows, n_cols = len(result), len(result[0])

    # Find columns that are completely uniform
    uniform_cols = set()
    for c in range(n_cols):
        col_vals = set(result[r][c] for r in range(n_rows))
        if len(col_vals) == 1:
            uniform_cols.add(c)

    # Find rows that are completely uniform  
    uniform_rows = set()
    for r in range(n_rows):
        row_vals = set(result[r])
        if len(row_vals) == 1:
            uniform_rows.add(r)

    # Fill uniform columns with 2s
    for c in uniform_cols:
        for r in range(n_rows):
            result[r][c] = 2

    # Fill uniform rows with 2s
    for r in uniform_rows:
        for c in range(n_cols):
            result[r][c] = 2

    return result

